const finite=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;
const types=['bed','sofa','chair','table','wardrobe','cabinet','toilet','bath','shower','sink'];
export function validateModel(value){if(!value||typeof value!=='object')throw Error('Ungültiges Modell.');const m=JSON.parse(JSON.stringify(value));if(!finite(m.width,1,100)||!finite(m.depth,1,100)||!finite(m.height,2,5))throw Error('Bitte gültige Außenmaße und eine Raumhöhe von 2–5 m verwenden.');if(!Array.isArray(m.walls)||m.walls.length<3||m.walls.length>160||!Array.isArray(m.rooms)||m.rooms.length>30||!Array.isArray(m.furniture)||m.furniture.length>100)throw Error('Zu viele oder zu wenige Modellelemente.');for(const w of m.walls){if(![w.x1,w.z1,w.x2,w.z2].every(n=>finite(n,0,1))||Math.hypot((w.x2-w.x1)*m.width,(w.z2-w.z1)*m.depth)<.04||!Array.isArray(w.openings)||w.openings.length>12)throw Error('Ungültiger Wandverlauf.');let end=0;w.openings.sort((a,b)=>a.start-b.start);for(const o of w.openings){if(!['door','window'].includes(o.kind)||!finite(o.start,0,1)||!finite(o.end,0,1)||o.start>=o.end||o.start<end)throw Error('Öffnungen müssen innerhalb der Wand liegen und dürfen sich nicht überlappen.');end=o.end}}
for(const r of m.rooms){if(typeof r.name!=='string'||r.name.length>80||!['wood','tile','outdoor'].includes(r.floor)||!Array.isArray(r.points)||r.points.length<3||r.points.length>32||r.points.some(p=>!finite(p.x,0,1)||!finite(p.z,0,1)))throw Error('Ungültige Raumfläche.');if(Math.abs(r.points.reduce((sum,p,i)=>{const q=r.points[(i+1)%r.points.length];return sum+p.x*q.z-q.x*p.z},0))<.00001)throw Error('Raumfläche ist zu klein.');}
for(const f of m.furniture)if(!types.includes(f.type)||![f.x,f.z].every(n=>finite(n,0,1))||!finite(f.width,.1,10)||!finite(f.depth,.1,10)||!finite(f.height,.1,4)||!finite(f.rotation,-360,360))throw Error('Ungültiges Möbelstück.');if(typeof m.notes!=='string'||m.notes.length>2000)throw Error('Ungültige Modellhinweise.');return m}
export function wallPieces(w,height){const parts=[];let cursor=0;const add=(a,b,bottom,top)=>{if(b>a&&top>bottom)parts.push({start:a,end:b,bottom,top})};for(const o of w.openings){add(cursor,o.start,0,height);if(o.kind==='window')add(o.start,o.end,0,Math.min(.9,height*.35));add(o.start,o.end,Math.min(o.kind==='door'?2.05:2.15,height*.9),height);cursor=o.end}add(cursor,1,0,height);return parts}
export const modelSchema={type:'object',additionalProperties:false,properties:{width:{type:'number'},depth:{type:'number'},height:{type:'number'},notes:{type:'string'},walls:{type:'array',items:{type:'object',additionalProperties:false,properties:{x1:{type:'number'},z1:{type:'number'},x2:{type:'number'},z2:{type:'number'},openings:{type:'array',items:{type:'object',additionalProperties:false,properties:{kind:{type:'string',enum:['door','window']},start:{type:'number'},end:{type:'number'}},required:['kind','start','end']}}},required:['x1','z1','x2','z2','openings']}},rooms:{type:'array',items:{type:'object',additionalProperties:false,properties:{name:{type:'string'},floor:{type:'string',enum:['wood','tile','outdoor']},points:{type:'array',items:{type:'object',additionalProperties:false,properties:{x:{type:'number'},z:{type:'number'}},required:['x','z']}}},required:['name','floor','points']}},furniture:{type:'array',items:{type:'object',additionalProperties:false,properties:{type:{type:'string',enum:types},x:{type:'number'},z:{type:'number'},width:{type:'number'},depth:{type:'number'},height:{type:'number'},rotation:{type:'number'}},required:['type','x','z','width','depth','height','rotation']}}},required:['width','depth','height','notes','walls','rooms','furniture']};
